using UnityEngine;using UnityEditor;using UnityEngine.Rendering.HighDefinition;
public static class CaptureSlopeFix {public static string Main(){GameObject floor=null,copy=null,camObject=null;RenderTexture rt=null;Texture2D tex=null;var old=RenderTexture.active;try{floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.rotation=Quaternion.Euler(-14,0,0);floor.transform.localScale=new Vector3(80,1,80);copy=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/Pickups/Driveable/Pick_up_Driveable.prefab"),new Vector3(10000,1,10000),Quaternion.identity);var b=copy.GetComponent<BicycleController>();b.SetRidden(true);Physics.SyncTransforms();for(int i=0;i<150;i++)b.Drive(0,0,true,.02f);camObject=new GameObject("Slope preview");var c=camObject.AddComponent<Camera>();c.enabled=false;camObject.AddComponent<HDAdditionalCameraData>();c.fieldOfView=45;c.transform.position=copy.transform.position+new Vector3(-10,2.2f,-2.4f);c.transform.LookAt(copy.GetComponent<VehicleGroundAlignment>().Pose.position+Vector3.up*.9f);rt=RenderTexture.GetTemporary(1200,850,24);c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex=new Texture2D(1200,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,850),0,0);tex.Apply();System.IO.File.WriteAllBytes("output/Pickups/SlopeGroundContact.png",tex.EncodeToPNG());c.targetTexture=null;return "Slope capture saved";}finally{RenderTexture.active=old;if(rt)RenderTexture.ReleaseTemporary(rt);if(tex)Object.DestroyImmediate(tex);if(camObject)Object.DestroyImmediate(camObject);if(copy)Object.DestroyImmediate(copy);if(floor)Object.DestroyImmediate(floor);}}}
